import {clsx} from "clsx";
import "./_index.css";

interface CatalogEntry {
  id: string;
  label: string;
  active: boolean;
}

export const CatalogPage = ({entries}: {entries: CatalogEntry[]}) => (
  <nav className="route_catalog">
    {entries.map((entry) => (
      <button
        key={entry.id}
        className={clsx("route_catalog__listButton", {
          "route_catalog__listButton--active": entry.active,
        })}
      >
        {entry.label}
      </button>
    ))}
  </nav>
);

.route_catalog__listButton {
  display: flex;
}

.route_catalog__listButton--active {
  color: var(--color-accent);
  font-weight: 700;
}

.route_catalog__listButton:hover {
  text-decoration: underline;
}
